  internal ActionResult Report(ActionResult result){Operation=result.Message;OperationFailed=!result.Success;return result;}
  internal async Task<ActionResult> Command(string op,Dictionary<string,object> args){if(ReadOnly&&op!="Capture"&&op!="Refresh")return Report(ActionResult.Fail("Read-only preview: no server or configuration action was performed."));if(Busy||Lifecycle.StartupPending)return Report(ActionResult.Fail("An operation is already active."));if(op!="Capture"&&op!="Refresh"&&(Telemetry.GetHost().Observation==ProcessObservation.Failed||Telemetry.GetHost().Observation==ProcessObservation.Unknown))return Report(ActionResult.Fail("Process observation unavailable. Wait for a confirmed process state."));Busy=true;ActionResult result;try{
